import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.F7eQ-ohH.js";const n="/bzygq/assets/quesion_imgs_c8084a23-b249-457e-8522-0e34ad2ca816.CGUt1Cp8.png",s="/bzygq/assets/quesion_imgs_43a4a61f-9f25-4068-aac4-e3b0d2e9f727.CGVRalxp.png",u=JSON.parse('{"title":"数据结构以及概念","description":"","frontmatter":{},"headers":[],"relativePath":"科技岗专业课/数据结构/1、数据结构和算法概念.md","filePath":"科技岗专业课/数据结构/1、数据结构和算法概念.md","lastUpdated":1788883925000}'),l={name:"科技岗专业课/数据结构/1、数据结构和算法概念.md"};function i(e,p,g,h,d,c){return r(),a("div",null,[...p[0]||(p[0]=[o('<h1 id="数据结构以及概念" tabindex="-1">数据结构以及概念 <a class="header-anchor" href="#数据结构以及概念" aria-label="Permalink to &quot;数据结构以及概念&quot;">​</a></h1><h2 id="数据结构概念" tabindex="-1">数据结构概念 <a class="header-anchor" href="#数据结构概念" aria-label="Permalink to &quot;数据结构概念&quot;">​</a></h2><p><strong>数据</strong>：数据是对客观事物的符号表示，它是计算机科学中的基础概念之一。在计算机科学领域，数据指的是所有可以被计算机接收并处理的信息，这些信息以各种符号形式存在，如数字、字符、图像等。</p><p><strong>数据元素</strong>：数据元素是构成数据的基本单位，是数据结构课程中最基础的研究对象。在计算机程序中，数据元素通常被视为一个整体来进行处理。一个数据元素可以由一个或多个数据项组成，每个数据项代表了数据元素的一个属性。例如一个List，Map或者Set都叫做一个数据元素，数据库的一张表也叫做数据元素。</p><p><strong>数据项（数据对象）</strong>：数据项是数据元素内部的最小单位，是构成数据元素的具体信息片段。例如，数据库中的一个User对象的数据元素可能包括姓名、年龄、性别等多个数据项。</p><p><img src="'+n+'" alt="图片"></p><p><strong>数据结构</strong>：数据结构是指相互之间存在一种或多种特定关系的数据元素的集合。它是计算机科学中的一个重要分支，主要研究数据的组织方式、处理方法以及它们之间的关系,数据结构包括三个核心方面：</p><ul><li><p><strong>逻辑结构</strong>：逻辑结构描述的是数据元素之间的抽象关系，不涉及具体的实现细节。逻辑结构主要分为两大类：线性结构和非线性结构。例如线性表就是一个逻辑结构，它的具体实现包含了数组和链表。</p></li><li><p><strong>存储结构</strong>：存储结构指的是数据元素在计算机中的存储方式，包括顺序结构、链式结构、索引结构和散列结构。</p></li><li><p><strong>运算</strong>：运算定义了在数据结构上可以执行的各种操作，如插入、删除、查找等。</p></li></ul><p><strong>数据的逻辑结构</strong>：根据数据元素之间关系的不同，逻辑结构可以分为线性结构和非线性结构。线性结构中，每个元素只有一个直接前驱和一个直接后继，如数组和链表；非线性结构中，元素之间的关系可以是一对多或多对多，如树和图。</p><p><strong>数据的物理结构（存储结构）</strong>：根据数据元素在计算机内存中的存储方式不同，物理结构可以分为以下几种：</p><ul><li><p><strong>顺序结构</strong>：顺序结构是最直观的存储方式，逻辑上相邻的元素在物理位置上也是相邻的。这种方式便于快速访问和处理，但插入和删除操作可能较为低效。</p></li><li><p><strong>链式结构</strong>：链式结构中，逻辑上相邻的元素在物理位置上不一定相邻，而是通过指针链接起来。这种方式在插入和删除操作上有优势，但在访问特定元素时可能不如顺序结构高效。</p></li><li><p><strong>索引结构</strong>：索引结构不仅存储数据本身，还维护了一个索引表，该表包含了关键字和对应的物理地址。索引结构提高了查找效率，特别适合于大型数据集。</p></li><li><p><strong>散列结构</strong>：散列结构是一种高效的存储方式，它通过散列函数将关键字转换为存储地址，实现了快速存取。散列结构在处理大数据集时非常有效，但也需要注意解决哈希冲突的问题。</p></li></ul><h2 id="真题练习" tabindex="-1">真题练习 <a class="header-anchor" href="#真题练习" aria-label="Permalink to &quot;真题练习&quot;">​</a></h2><p>【国家电网2014年|||在决定选取何种存储结构时，一般不考虑（ ）</p><p>A. 各结点的值如何</p><p>B. 结点个数的多少</p><p>C. 对数据有哪些运算</p><p>D. 所用的编程语言实现这种结构是否方便</p><p>答案：A</p><p>解析：选存储结构只看节点数量、要做的运算和编程语言实现是否方便，不看节点里具体存什么值，所以答案选A】</p><p>【国家电网2017|||某数据库中的学生信息表，包含学号、姓名、专业等字段。对该表进行如下操作：① 按照学号顺序连续存储在内存中② 为快速按专业查询，建立专业→学号的索引表③ 将学生信息组织成树形结构显示院系-专业-学生的层次关系上述操作分别涉及的数据结构特征是：</p><p>A. ①物理结构 ②物理结构 ③逻辑结构</p><p>B. ①逻辑结构 ②物理结构 ③逻辑结构</p><p>C. ①物理结构 ②逻辑结构 ③物理结构</p><p>D. ①逻辑结构 ②逻辑结构 ③物理结构</p><p>答案：A</p><p>解析：操作①：顺序存储方式 → 物理（存储）结构操作②：建立索引表 → 物理（存储）结构（索引存储）操作③：树形关系描述 → 逻辑结构（非线性结构）】</p><h1 id="算法及其基本概念" tabindex="-1">算法及其基本概念 <a class="header-anchor" href="#算法及其基本概念" aria-label="Permalink to &quot;算法及其基本概念&quot;">​</a></h1><h2 id="思维导图" tabindex="-1">思维导图 <a class="header-anchor" href="#思维导图" aria-label="Permalink to &quot;思维导图&quot;">​</a></h2><p><img src="'+s+'" alt="图片"></p><h2 id="算法基本概念" tabindex="-1">算法基本概念 <a class="header-anchor" href="#算法基本概念" aria-label="Permalink to &quot;算法基本概念&quot;">​</a></h2><p><strong>算法</strong>：算法是一组明确定义的指令集合，用于解决特定问题或执行特定任务。它是计算机科学的核心概念之一，指导着计算机如何有效地处理数据。</p><p><strong>算法特征</strong>：</p><ul><li><p><strong>有穷性</strong>：任何算法都必须在有限的步骤内完成，不能无限循环。</p></li><li><p><strong>确切性</strong>：算法的每一步都应该是清晰且无歧义的，确保执行过程中的准确性。</p></li><li><p><strong>输入</strong>：算法可以接受零个或多个输入值，这些输入是算法开始执行时提供的。</p></li><li><p><strong>输出</strong>：算法至少产生一个输出结果，这是算法执行的最终目的。</p></li><li><p><strong>可行性</strong>：算法描述的操作应该是现实中可实现的，不应包含理论上无法完成的任务。</p></li></ul><p><strong>算法评价标准</strong>：</p><ul><li><p><strong>健壮性</strong>：算法应该能够处理各种异常情况，即使输入数据不符合预期，也不应导致程序崩溃。</p></li><li><p><strong>可读性</strong>：算法的描述应该清晰易懂，便于其他开发者阅读和维护。</p></li><li><p><strong>正确性</strong>：算法必须能够正确地解决问题，产生预期的结果。</p></li><li><p><strong>时间复杂度</strong>：时间复杂度是衡量算法执行效率的重要指标，它反映了算法随着输入规模增长而增加的计算工作量。时间复杂度通常用大O符号表示，如O(1)、O(n)、O(log n)等。</p></li><li><p><strong>空间复杂度</strong>：空间复杂度衡量算法在运行过程中所需的额外存储空间。它不仅包括输入数据所占的空间，还包括算法执行过程中动态分配的临时空间。空间复杂度同样用大O符号表示。</p></li></ul><p><strong>算法描述方法</strong>：</p><ul><li><p><strong>自然语言</strong>：自然语言描述算法是一种直观的方式，适用于初步设计阶段，但可能不够精确。</p></li><li><p><strong>流程图</strong>：流程图通过图形化的方式展示算法的逻辑流程，有助于理解算法的各个步骤。</p></li><li><p><strong>伪代码</strong>：伪代码是一种介于自然语言和编程语言之间的描述方式，它既保持了自然语言的可读性，又具备编程语言的结构性，是算法设计中常用的工具。</p></li></ul><p><strong>时间复杂度计算</strong>：掌握如何计算算法的时间复杂度是算法分析的基础。时间复杂度的计算通常基于算法中基本操作的执行次数，通过分析这些操作的频率来评估算法的效率。例如，对于一个简单的循环，如果循环体内的操作执行了n次，那么该算法的时间复杂度为O(n)。</p><h2 id="真题练习-1" tabindex="-1">真题练习 <a class="header-anchor" href="#真题练习-1" aria-label="Permalink to &quot;真题练习&quot;">​</a></h2><p>【国家电网（2014）|||一个算法必须在执行有穷步之后结束，这是算法的（ ）</p><p>A. 正确性</p><p>B. 有穷性</p><p>C. 确定性</p><p>D. 可行性</p><p>答案：B</p><p>解析：算法的有穷性定义就是 “执行有限步骤后必须结束”，A 是指算法结果正确，C 是步骤无歧义，D 是步骤可实现，均不符合题意。】</p><p>【国家电网（2016）|||</p><p>对一个算法的评价，不包括如下（ ）方面的内容</p><p>A. 健壮性和可读性</p><p>B. 并行性</p><p>C. 正确性</p><p>D. 时空复杂度</p><p>答案：B</p><p>解析：算法评价核心看正确性、健壮性、可读性、时空复杂度，并行性是程序执行方式，不是算法的评价维度。】</p><p>【国家电网（2018）|||算法指的是（ ）</p><p>A. 计算机程序B. 解决问题的计算方法</p><p>C. 排序算法</p><p>D. 解决问题的有限运算序列</p><p>解析：算法的标准定义是 “解决问题的有限运算序列”，A 中程序是算法的实现形式而非算法本身，B 表述太笼统，C 只是算法的一种具体类型。正确</p><p>答案：D】</p><p>【国家电网（2020）||| 算法设计的要求包括（ ）</p><p>A. 正确性</p><p>B. 可读性</p><p>C. 健壮性</p><p>D. 确定性</p><p>解析：算法设计的要求包括正确性（结果准确）、可读性（易理解）、健壮性（抗异常输入），D 是算法的基本特性（步骤无歧义），并非设计要求。正确</p><p>答案：A、B、C（多选题）】</p><p>【国家电网（2015）|||下列关于算法的叙述中，错误的是（ ）</p><p>A. 算法是问题的程序化解决方案</p><p>B. 算法必须有输出</p><p>C. 算法必须在有限步骤内结束</p><p>D. 算法可以没有输入正确</p><p>答案：A</p><p>解析：算法是 “解决问题的有限运算序列”，而非 “程序化解决方案”（程序化是程序的特点）；算法必须有输出（至少 1 个），可无输入，且需有限步骤结束，B、C、D 均正确。】</p><h1 id="考点速记" tabindex="-1">考点速记 <a class="header-anchor" href="#考点速记" aria-label="Permalink to &quot;考点速记&quot;">​</a></h1><h2 id="数据结构核心速记" tabindex="-1">数据结构核心速记 <a class="header-anchor" href="#数据结构核心速记" aria-label="Permalink to &quot;数据结构核心速记&quot;">​</a></h2><p>三大基本单位：数据（计算机可处理的符号）→ 数据元素（基本单位，如 List、数据库表）→ 数据项（最小单位，如姓名、学号）</p><p>数据结构三要素：逻辑结构（元素关系）、存储结构（物理存储）、运算（插入 / 删除 / 查找等）</p><p>逻辑结构分类：线性结构（一对一，如数组、链表）、非线性结构（一对多 / 多对多，如树、图）</p><p>存储结构 4 种类型及关键特点：</p><ul><li><p><strong>顺序结构</strong>：物理相邻，查快（O (1)），增删慢（移元素）</p></li><li><p><strong>链式结构</strong>：指针链接，增删快（改指针），查慢（遍历）</p></li><li><p><strong>索引结构</strong>：含索引表（关键字 + 地址），查快，适配动态增删</p></li><li><p><strong>散列结构</strong>：哈希函数映射地址，查极快（近 O (1)），需解决冲突</p></li></ul><p>存储结构选择依据：节点个数、运算需求（查 / 增删频率）、编程语言实现难度（不看节点具体值）</p><h2 id="算法核心速记" tabindex="-1">算法核心速记 <a class="header-anchor" href="#算法核心速记" aria-label="Permalink to &quot;算法核心速记&quot;">​</a></h2><p>算法定义：解决问题的<strong>有限运算序列</strong>（≠程序、≠笼统方法）</p><p>算法五大特征：有穷性（有限步骤结束）、确切性（步骤无歧义）、输入（0 个或多个）、输出（至少 1 个）、可行性（操作可实现）</p><p>算法评价标准：正确性、健壮性（抗异常）、可读性、时空复杂度（≠并行性）</p><p>算法设计要求：正确性、可读性、健壮性（确定性是特征，非要求）</p><p>复杂度核心：时间复杂度（执行效率，如 O (1)、O (n)）、空间复杂度（额外存储空间），均用大 O 符号表示</p>',88)])])}const m=t(l,[["render",i]]);export{u as __pageData,m as default};
